/*
 * prog17_whitespace_trim.c
 *
 * Re‑implementation of the original program's observable behaviour.
 *
 * The program expects a single command‑line argument.  It trims leading and
 * trailing whitespace, collapses any internal run of whitespace characters
 * (space, tab, newline, vertical tab, form‑feed, carriage‑return) to a single
 * space, and prints the resulting string.  If no argument is supplied, or the
 * trimmed result is empty, the program prints the literal string "EMPTY".
 *
 * The original binary limited the processed input to the first 1024 characters;
 * this implementation does the same.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_INPUT 1024   /* maximum number of characters to consider */

int main(int argc, char **argv)
{
    /* No argument → print EMPTY */
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }

    const char *src = argv[1];
    size_t src_len = strlen(src);
    if (src_len > MAX_INPUT) {
        src_len = MAX_INPUT;          /* cap to 1024 characters */
    }

    char out[MAX_INPUT + 1];          /* output buffer (including NUL) */
    size_t out_len = 0;

    size_t i = 0;

    /* Skip leading whitespace */
    while (i < src_len && isspace((unsigned char)src[i])) {
        ++i;
    }

    int prev_was_space = 0;           /* true if the previous processed char was whitespace */

    for ( ; i < src_len; ++i) {
        unsigned char ch = (unsigned char)src[i];

        if (isspace(ch)) {
            /* Remember that we have seen whitespace; we will emit a single space
               before the next non‑whitespace character (if any). */
            prev_was_space = 1;
        } else {
            /* If we just passed a run of whitespace and we already have output,
               insert a single space before the current character. */
            if (prev_was_space && out_len > 0) {
                out[out_len++] = ' ';
            }
            out[out_len++] = (char)ch;
            prev_was_space = 0;
        }
    }

    out[out_len] = '\0';              /* NUL‑terminate */

    if (out_len == 0) {
        puts("EMPTY");
    } else {
        puts(out);
    }

    return 0;
}
